import openpyxl, datetime
wb=openpyxl.load_workbook('task/output.xlsx'); ws=wb['Data']
new_cols=['AD','AE','AF','AG','AH','AI','AJ','AK','AL','AM','AN','AO']
base_cols=['Q','R','S','T','U','V','W','X','Y','Z','AA','AB']
def edate(d,m):
    y=d.year; mo=d.month+m
    return datetime.date(y+(mo-1)//12, (mo-1)%12+1, 1)
def val(r,nc,bc):
    L=ws[f'L{r}'].value; J=ws[f'J{r}'].value
    if not isinstance(J,(int,float)) or not isinstance(L,(datetime.datetime,datetime.date)):
        return None
    D=ws[f'{nc}9'].value
    if isinstance(D,datetime.datetime): D=D.date()
    if isinstance(L,datetime.datetime): L=L.date()
    if D<L: return None
    base=ws[f'{bc}{r}'].value
    mult=(1+ws[f'M{r}'].value)
    if D>=edate(L,int(J)): mult*=(1+ws[f'N{r}'].value)
    if D>=edate(L,2*int(J)): mult*=(1+ws[f'O{r}'].value)
    if D>=edate(L,3*int(J)): mult*=(1+ws[f'P{r}'].value)
    return base*mult
for r in [14,17,40,15,36]:
    for nc,bc in zip(new_cols,base_cols):
        exp=val(r,nc,bc)
        got=ws[f'{nc}{r}'].value
        if exp is None:
            ok = (got is None or got=='')
        else:
            ok = got is not None and abs(got-exp)<0.01
        if not ok:
            print('MISMATCH', nc, r, 'exp',exp,'got',got)
print('verification complete')
